export function getDestinationBySlug(slug: string): Destination | undefined {
  const normalized = slug.toLowerCase().trim();
  return ALL_DESTINATIONS.find(
    (d) =>
      d.slug.toLowerCase() === normalized ||
      d.id.toLowerCase() === normalized ||
      d.name.toLowerCase().replace(/\s+/g, '-') === normalized
  );
}

export function getDestinationsByState(stateSlug: string): Destination[] {
  const normalized = stateSlug.toLowerCase().trim();
  return ALL_DESTINATIONS.filter(
    (d) => d.state.slug.toLowerCase() === normalized
  );
}

export function getTrendingDestinations(limit: number = 8): Destination[] {
  return ALL_DESTINATIONS.filter((d) => d.is_trending).slice(0, limit);
}

export function getHiddenGems(limit: number = 8): Destination[] {
  return ALL_DESTINATIONS.filter((d) => d.is_hidden_gem).slice(0, limit);
}

export function getDestinationsByCategory(category: string): Destination[] {
  return ALL_DESTINATIONS.filter((d) => d.category === category);
}

export function getAllDestinations(): Destination[] {
  return ALL_DESTINATIONS;
}
